  "lh-sub": "A decentralised network cannot check whether a real company stands behind an account, and it should not have to: no registry, no authority, no gatekeeper. Instead, hoarding is expensive in every form and passing money on is cheap in every form. Registering as a business only pays off for those whose money really flows.",
  "lh-list-h": "Every workaround we found, and why it fails",
  "lh-1": "<strong>Registering as a business to get around the 25,000 limit.</strong> The idle-money levy of 1–3 % a month is more expensive than any other form.",
  "lh-2": "<strong>Sending money in circles between your own or friendly firms.</strong> The age travels with the money; between businesses nothing gets younger, however long the circle.",
  "lh-3": "<strong>Paying it back through the owner or a friend.</strong> If the money stayed with that person for less than 30 days, it keeps its age.",
  "lh-4": "<strong>Really parking it with friends for 30 days.</strong> Every person can hold at most 25,000 AEQ and pays the surcharge both ways: about 2–2.5 % per round to save 1–3 %, at full risk.",
