  "step3-h": "Recibir",
  "step3-p": "1.000 AEQ una vez por registro exitoso.",
  "sybil-blurb": "<strong>Sybil / protección:</strong> verificación facial en vivo (quórum 2 de servicios independientes) + atestación firmada + nullifier en cadena, gastado una sola vez. Límites declarados: las cuentas anteriores a la verificación facial (25/08/2026 — casi todas las 18 de hoy) no tienen plantilla facial; el umbral de comparación aún no está calibrado con capturas reales; la prueba de vida es un giro de cabeza, los deepfakes avanzados siguen siendo un riesgo residual; el modo de partes (<code>MPC</code>) corre en sombra, cada servicio sigue guardando una plantilla cifrada completa.",
