  "why-link": "Curva de Lorenz, historial y la comparación entre países →",
  "disc-title": "Aviso Phase 1",
  "disc-body": "Phase 1: desde el 25/08/2026 el servidor de pruebas rechaza todo registro sin la atestación firmada del quórum de comparación — un segundo teléfono ya no da una segunda cuenta al mismo rostro. Lo que aún no se cumple: las cuentas anteriores a esa fecha no tienen plantilla facial y en principio podrían registrarse de nuevo con otra cartera; las tasas de error no están calibradas (hacen falta ~1.000 pares de impostores); la prueba de vida es un giro de cabeza, las defensas más fuertes contra deepfakes están en calibración. Lee «un humano, una cuenta» como «verificado, con límites declarados» — no como «imposible de eludir».",
