  "fee-note": "La comisión se suma encima: el destinatario recibe siempre el importe completo, así que un precio de 10 AEQ le da a la tienda exactamente 10 AEQ. Desde el 1 de octubre de 2026 los primeros 1.000 AEQ que una persona gasta al mes son gratis, y los salarios de empresas a personas no cuestan nada. Entre empresas se paga el 0,1 % sin recargo.",
