  "ex-ben-h": "Ben trabaja en un café",
  "ex-ben-p": "Gana 2.000 AEQ de salario, gasta 1.500 AEQ y cambia 1.000 AEQ a euros para el alquiler. Comisión sobre los 500 AEQ por encima de su importe libre: 0,5 AEQ. Comisión normal de cambio: 1 AEQ. Sin gravamen de salida, porque es su salario.",
  "ex-ben-r": "paga 1,5 AEQ al mes",
  "ex-clara-h": "Clara tiene 20.000 AEQ",
  "ex-clara-p": "Gasta 3.000 AEQ al mes y cambia 5.000 AEQ. Transferencias: 2.000 × 1,1 % = 22 AEQ. Dinero parado: 15.000 × 0,5 % = 75 AEQ. Cambio: 4.000 × 2 % = 80 AEQ (los primeros 1.000 son libres). Todo va a la renta básica, también a Anna y Ben.",
  "ex-clara-r": "paga 177 AEQ al mes",
