  "how-label": "Как это работает",
  "how-h2": "Три честных шага (Phase 1)",
  "how-sub": "Кошелёк на телефоне, короткая живая съёмка лица и разовое начисление — без банковского счёта.",
  "step1-h": "Снять",
  "step1-p": "Кошелёк на телефоне; приложение снимает ваше лицо со случайным поворотом головы, и две независимые службы сравнения сверяют его со всеми, кто зарегистрирован с начала проверки лица. Изображения удаляются; каждая служба хранит зашифрованный шаблон.",
  "step2-h": "Доказать",
  "step2-p": "Доказательство с нулевым разглашением цепи: эта привязанная к лицу личность ещё не зарегистрирована (nullifier). Сервер доказательств принимает его только с подписанным подтверждением служб сравнения.",
  "step3-h": "Получить",
  "step3-p": "1 000 AEQ один раз за успешную регистрацию.",
  "sybil-blurb": "<strong>Sybil / защита:</strong> живая проверка лица (кворум 2 независимых служб) + подписанное подтверждение + nullifier в цепи, тратится один раз. Названные ограничения: счета, созданные до проверки лица (25.08.2026 — почти все из сегодняшних 18), не имеют шаблона лица; порог сравнения ещё не откалиброван на реальных снимках; проверка живости — поворот головы, продвинутые дипфейки остаются остаточным риском; режим долей (<code>MPC</code>) работает в тени, каждая служба по-прежнему хранит целый зашифрованный шаблон.",
  "how-link": "Зарегистрироваться и получить свои 1 000 AEQ →",
  "why-label": "Справедливость",
  "why-h2": "Коэффициент Джини у Bitcoin ~0,85 — выше, чем в любой стране",
  "why-sub": "Предложение = подтверждённые люди × 1 000 AEQ. Gini с живого узла. Go L1 — источник истины реестра (не только зеркальный контракт).",
  "why-link": "Кривая Лоренца, история и сравнение со странами →",
  "disc-title": "Оговорка Phase 1",
  "disc-body": "Phase 1: с 25.08.2026 сервер доказательств отклоняет любую регистрацию без подписанного подтверждения кворума сравнения — второй телефон больше не даёт тому же лицу второй счёт. Что пока не выполняется: счета, созданные до этой даты, не имеют шаблона лица и в принципе могли бы зарегистрироваться снова на новый кошелёк; частота ошибок не откалибрована (нужно ~1 000 импостор-пар); проверка живости — поворот головы, более сильная защита от дипфейков калибруется. Читайте «один человек — один счёт» как «проверено, с названными ограничениями», а не как «невозможно обойти».",
  "oss-line": "<strong>Открытый код:</strong> Ядро цепи публично · сервисы identity/proof частично закрыты в Phase 1.",
  "rest-label": "Остальная часть сайта",
