  "rest-sub": "Эта страница намеренно на этом заканчивается. Каждый раздел ниже содержит подробности — вживую с этого узла, а не переписанные сюда во второй раз.",
  "card-register-d": "Пройдите проверку и получите 1 000 AEQ, которые полагаются каждому человеку.",
  "card-explorer-d": "Блоки, транзакции и реестр людей — по мере того, как они появляются.",
