  "eco-p1-h": "Деньги создаются только для людей",
  "eco-p1-p": "Каждый проверенный человек один раз получает 1 000 AEQ. Больше никто не создаёт деньги: ни компании, ни валидаторы, ни основатели.",
  "eco-p2-h": "Оборот вознаграждается",
  "eco-p2-p": "Покупки, выплата зарплат и расчёты с поставщиками стоят мало или ничего. Деньги, лежащие сверх ясных пределов, платят небольшой ежемесячный сбор.",
