  "card-explorer-d": "区块、交易与人类注册表，实时呈现。",
  "card-equality-d": "完整的基尼系数：洛伦兹曲线、历史记录、财富上限。",
  "card-network-d": "共识、节点、基本收入、滞留费与监护人 — 规则本身。",
  "card-exchange-d": "兑换与流动性。转账手续费 100% 进入 UBI；兑换手续费按 40 / 30 / 30 分配。",
  "card-social-d": "X 与 Telegram — 公告，以及那些不好回答的问题。",
