  "cmp-r5-b": "%2",
  "cmp-r6": "Kim açar",
  "cmp-r6-p": "doğrulanmış her insan, bir kez",
  "cmp-r6-b": "bir ila on doğrulanmış insan; kişi başı en fazla 3",
  "cmp-r6-f": "herkes",
  "cmp-note": "Bu kurallar 1 Ekim 2026'dan itibaren geçerlidir. Her kesinti %100 temel gelire gider.",
  "ppl-label": "İnsanlar için",
  "ppl-h2": "Her insana altı söz",
  "ppl-sub": "En adil para, önce az şeyi olan insana adil hissettirmelidir.",
  "ppl-1": "<strong>Adil payın dokunulmazdır.</strong> İlk 1.000 AEQ asla kesintiye uğramaz.",
  "ppl-2": "<strong>Günlük hayat hiçbir şeye mal olmaz.</strong> Her ay harcadığın ilk 1.000 AEQ ücretsizdir.",
  "ppl-3": "<strong>Maaş maaştır.</strong> Ayda 3.000 AEQ'ya kadar maaş ve buna ek 1.000 AEQ kesintisiz çevrilir.",
  "ppl-4": "<strong>Birikim yapmak serbesttir.</strong> 5.000 AEQ'ya kadar birikimin hiçbir şey kaybetmez.",
  "ppl-5": "<strong>Daha çok olan daha çok katkı yapar.</strong> Ücretler yalnızca büyük bakiyelerde artar; 25.000 AEQ sınırı kalır.",
  "ppl-6": "<strong>İnsanlar tutmak ve çıkmak için her zaman işletmelerden daha az öder,</strong> ve kim ne öderse, tüm insanlara eşit olarak geri döner.",
  "biz-label": "İşletmeler için",
  "biz-h2": "AEQ kabul et, aktar, hiçbir şey ödeme",
  "biz-sub": "İşletmeler AEQ kabul edebilir, tutabilir ve harcayabilir. Kurallar parayı işletmelerin içinden geçirip insanlara geri akıtır: bekletmek maliyetlidir, aktarmak ücretsizdir.",
  "biz-b1-h": "Kart komisyonu yok",
  "biz-b1-p": "Bir ödeme işletmeye hiçbir şeye mal olmaz. Müşteriler her ay ilk 1.000 AEQ'yu ücretsiz harcar.",
  "biz-b2-h": "Ücretsiz maaş ödemesi",
  "biz-b2-p": "AEQ ile ödenen maaşlar hiçbir maliyet yaratmaz. Çalışanlar ayda 3.000 AEQ'ya kadar maaşı kesintisiz avro veya dolara çevirebilir.",
  "biz-b3-h": "Büyüme sınırı yok",
  "biz-b3-p": "İnsanlar en fazla 25.000 AEQ tutabilir; işletmelerin sabit bir sınırı yoktur. 30 gün içinde dolaşıma devam eden para hiçbir zaman maliyet yaratmaz.",
  "biz-b4-h": "Saniyeler içinde ödeme",
  "biz-b4-p": "Para saniyeler içinde gelir. Ters ibraz yok, mutabakat beklemek yok.",
  "biz-rules-h": "Kurallar",
  "biz-r1-k": "Bekleyen para",
  "biz-r1-v": "30 günden eski: ayda %1 · 90 günden eski: ayda %3 · 2.000 AEQ her zaman ücretsiz",
  "biz-r2-k": "Paranın bir yaşı var",
  "biz-r2-v": "Yaş parayla birlikte yolculuk eder. Parayı kendi şirketlerin veya arkadaşların üzerinden döndürmek onu yeni yapmaz. Para ancak bir insanda 30 gün kaldıktan sonra yeni olur.",
  "biz-r3-k": "Avro veya dolara çıkış",
  "biz-r3-v": "%2 kesinti. İnsanlar: maaş ve ayda 1.000 AEQ ücretsiz",
  "biz-r4-k": "İşletmeler arası",
  "biz-r4-v": "%0,1, ek ücret yok",
  "biz-r5-k": "Nereye gider",
  "biz-r5-v": "Her kesinti %100 temel gelire gider, her insana eşit olarak",
  "biz-open": "<strong>İşletme hesabı açmak:</strong> doğrulanmış bir insan ve işletme cüzdanı birlikte imzalar. Kişi başına en fazla 3 işletme, işletme başına en fazla 10 sorumlu. Sicil dairesi yok, kapı bekçisi yok: kimse senin ne olduğunu kontrol etmez, kurallar her türlü istiflemeyi pahalı hale getirir. Yakında uygulamada.",
  "biz-live-from": "Kurallar geçerli",
  "biz-live-count": "Kayıtlı işletmeler",
  "biz-link": "Konseptin tamamını oku →",
