  "eco-svg-daily": "chaque jour, égal pour tous",
  "eco-svg-levies": "argent dormant · sortie · frais",
  "eco-p1-h": "L'argent n'est créé que pour les personnes",
  "eco-p1-p": "Chaque personne vérifiée reçoit 1 000 AEQ une seule fois. Personne d'autre ne crée d'argent : ni entreprises, ni validateurs, ni fondateurs.",
  "eco-p2-h": "La circulation est récompensée",
