  "eco-p3-h": "Chaque prélèvement revient à tous",
  "eco-p3-p": "Frais de transfert, prélèvements sur l'argent dormant et prélèvements de sortie vont à 100 % au revenu de base, versé chaque jour à parts égales à chaque personne vérifiée.",
  "cmp-label": "Personne ou entreprise ?",
