  "ppl-label": "Pour les personnes",
  "ppl-h2": "Six promesses à chaque personne",
  "ppl-sub": "L'argent le plus juste doit d'abord paraître juste à celui qui a peu.",
  "ppl-1": "<strong>Votre juste part est intouchable.</strong> Les 1 000 premiers AEQ ne paient jamais de prélèvement.",
  "ppl-2": "<strong>La vie quotidienne ne coûte rien.</strong> Les 1 000 premiers AEQ que vous dépensez chaque mois sont sans frais.",
  "ppl-3": "<strong>Un salaire est un salaire.</strong> Jusqu'à 3 000 AEQ de salaire par mois, plus 1 000 AEQ, s'échangent sans prélèvement.",
  "ppl-4": "<strong>Épargner est permis.</strong> Jusqu'à 5 000 AEQ, votre épargne ne perd rien.",
  "ppl-5": "<strong>Qui a plus contribue plus.</strong> Les frais n'augmentent qu'avec de gros soldes ; la limite de 25 000 AEQ demeure.",
  "ppl-6": "<strong>Les personnes paient toujours moins que les entreprises</strong> pour détenir et sortir, et tout ce que chacun paie revient à parts égales à toutes les personnes.",
  "biz-label": "Pour les entreprises",
  "biz-h2": "Acceptez l'AEQ, faites-le circuler, ne payez rien",
  "biz-sub": "Les entreprises peuvent accepter, détenir et dépenser de l'AEQ. Les règles font passer l'argent par elles et le ramènent aux personnes : le laisser dormir coûte, le faire circuler est gratuit.",
  "biz-b1-h": "Pas de frais de carte",
  "biz-b1-p": "Un paiement ne coûte rien à l'entreprise. Les clients dépensent leurs 1 000 premiers AEQ chaque mois sans frais.",
  "biz-b2-h": "Salaires sans frais",
  "biz-b2-p": "Les salaires versés en AEQ ne coûtent rien. Les salariés peuvent échanger jusqu'à 3 000 AEQ de salaire par mois en euros ou en dollars sans prélèvement.",
  "biz-b3-h": "Pas de plafond de croissance",
  "biz-b3-p": "Une personne peut détenir au plus 25 000 AEQ ; les entreprises n'ont pas de limite fixe. L'argent qui repart dans les 30 jours ne coûte jamais rien.",
  "biz-b4-h": "Payé en quelques secondes",
  "biz-b4-p": "L'argent arrive en quelques secondes. Pas de rétrofacturation, pas d'attente de règlement.",
  "biz-rules-h": "Les règles",
  "biz-r1-k": "Argent dormant",
  "biz-r1-v": "Plus de 30 jours : 1 % par mois · plus de 90 jours : 3 % par mois · 2 000 AEQ toujours libres",
  "biz-r2-k": "L'argent a un âge",
  "biz-r2-v": "L'âge voyage avec l'argent. Le faire tourner en rond, par ses propres sociétés ou par des amis, ne le rend pas neuf. Il ne redevient neuf qu'après 30 jours chez une personne.",
  "biz-r3-k": "Sortie en euro ou en dollar",
