  "biz-r5-k": "Où cela va",
  "biz-r5-v": "Chaque prélèvement va à 100 % au revenu de base, à parts égales pour chaque personne",
  "biz-open": "<strong>Ouvrir un compte entreprise :</strong> une personne vérifiée et le portefeuille de l'entreprise signent ensemble. Au plus 3 entreprises par personne, jusqu'à 10 responsables par entreprise. Pas de registre ni de contrôleur : personne ne vérifie ce que vous êtes, les règles rendent la thésaurisation coûteuse sous toutes ses formes. Bientôt dans l'application.",
  "biz-live-from": "Règles en vigueur à partir du",
