  "toc-faq": "Questions",
  "ubi-label": "Revenu de base",
  "ubi-h2": "Chaque jour, parts égales pour tous",
  "ubi-sub": "Aucune monnaie n’est créée pour le revenu de base. Il est payé uniquement avec ce que le réseau perçoit, et tout ce qui est perçu est reversé.",
  "ubi-c1-h": "Départ : 1 000 AEQ",
  "ubi-c1-p": "Chaque personne vérifiée reçoit une fois 1 000 AEQ à l’inscription : la juste part. La masse monétaire est toujours personnes vérifiées × 1 000 AEQ.",
  "ubi-c2-h": "Chaque jour à 20 h",
  "ubi-c2-p": "Chaque jour à 20 h (heure de Berlin), le fonds est partagé à parts égales entre toutes les personnes vérifiées. Ensuite, il repart de zéro.",
  "ubi-c3-h": "D’où il vient",
  "ubi-c3-p": "Frais de transfert (100 %), 30 % des frais de swap, le prélèvement sur l’argent dormant, le prélèvement de sortie de 2 % et tout ce qui dépasse le plafond de 25 000 AEQ.",
  "ubi-c4-h": "Qui le reçoit",
  "ubi-c4-p": "Seulement les personnes vérifiées. Entreprises, validateurs, fondateurs et autres adresses ne reçoivent rien.",
  "ubi-note": "La taille de la part quotidienne dépend de la quantité d’argent qui circule : plus l’AEQ circule, plus il revient à tous.",
  "fee-h": "Les frais de transfert en détail",
