  "pill-phase": "<strong>Phase 1</strong>",
  "stat-humans-lbl": "Humanos verificados",
  "stat-supply-lbl": "AEQ em circulação",
  "stat-gini-lbl": "Gini",
  "stat-blocks-lbl": "Blocos",
  "ubi-pre": "Próxima divisão igual em",
  "ubi-mid": "· o pool contém",
  "how-label": "Como funciona",
  "how-h2": "Três passos honestos (Phase 1)",
  "how-sub": "Carteira no telemóvel, uma breve captação facial ao vivo e uma atribuição única — sem conta bancária.",
  "step1-h": "Digitalizar",
  "step1-p": "Carteira no telemóvel; a app capta o seu rosto com um movimento de cabeça aleatório e dois serviços de comparação independentes comparam-no com todos os registados desde o início da verificação facial. As imagens são descartadas; cada serviço guarda um modelo cifrado.",
  "step2-h": "Provar",
  "step2-p": "Prova de conhecimento zero para a cadeia: esta identidade ligada ao rosto ainda não está registada (nullifier). O servidor de provas só a aceita com a atestação assinada dos serviços de comparação.",
  "step3-h": "Receber",
  "step3-p": "1.000 AEQ uma vez por registo bem-sucedido.",
  "sybil-blurb": "<strong>Sybil / proteção:</strong> verificação facial ao vivo (quórum 2 de serviços independentes) + atestação assinada + nullifier on-chain, gasto uma única vez. Limites declarados: as contas anteriores à verificação facial (25/08/2026 — quase todas as 18 de hoje) não têm modelo facial; o limiar de comparação ainda não está calibrado com captações reais; a prova de vida é um movimento de cabeça, deepfakes avançados continuam a ser um risco residual; o modo de partes (<code>MPC</code>) corre em sombra, cada serviço guarda ainda um modelo cifrado inteiro.",
  "how-link": "Registre-se e receba seus 1.000 AEQ →",
  "why-label": "Equidade",
  "why-h2": "O Gini do Bitcoin é ~0,85 — maior que o de qualquer país",
  "why-sub": "Oferta = humanos verificados × 1.000 AEQ. Gini do nó ao vivo. Go L1 é a fonte de verdade do ledger (não só o contrato espelho).",
  "why-link": "Curva de Lorenz, histórico e a comparação entre países →",
  "disc-title": "Aviso Phase 1",
  "disc-body": "Phase 1: desde 25/08/2026 o servidor de provas recusa qualquer registo sem a atestação assinada do quórum de comparação — um segundo telemóvel já não dá uma segunda conta ao mesmo rosto. O que ainda não se verifica: as contas anteriores a essa data não têm modelo facial e, em princípio, poderiam registar-se de novo noutra carteira; as taxas de erro não estão calibradas (são precisos ~1.000 pares de impostores); a prova de vida é um movimento de cabeça, defesas mais fortes contra deepfakes estão em calibração. Leia «um humano, uma conta» como «verificado, com limites declarados» — não como «impossível de contornar».",
  "oss-line": "<strong>Código aberto:</strong> Cadeia core pública · serviços de identidade/prova parcialmente privados na Phase 1.",
  "rest-label": "O resto do site",
  "rest-h2": "Todo o resto tem a sua própria seção",
  "rest-sub": "Esta página para aqui de propósito. Cada seção abaixo contém o detalhe — servido ao vivo por este nó, não escrito aqui uma segunda vez.",
  "card-register-d": "Verifique-se e receba os 1.000 AEQ que vêm com ser humano.",
  "card-explorer-d": "Blocos, transações e o registro de humanos conforme acontecem.",
  "card-equality-d": "O coeficiente de Gini por inteiro: curva de Lorenz, histórico, teto de riqueza.",
  "card-network-d": "Consenso, nós, renda básica, demurrage e guardiões — as próprias regras.",
  "card-exchange-d": "Swap e liquidez. As taxas de transferência vão 100% para a UBI; as de swap se dividem 40 / 30 / 30.",
  "card-social-d": "X e Telegram — anúncios e as perguntas incômodas.",
  "soc-label": "Redes sociais",
  "soc-h2": "Onde a rede fala",
  "soc-sub": "Anúncios, o estado da cadeia e as perguntas incômodas &mdash; em público, em ambas.",
  "soc-x-d": "Anúncios, e o que a cadeia está realmente fazendo. Formato curto.",
  "soc-tg-d": "O grupo aberto: perguntas, operadores de nós e ajuda para se registrar.",
  "foot-launched": "Lançada em junho de 2026",
  "foot-phase": "Phase 1",
  "foot-quote": "O dinheiro existe porque as pessoas existem. Nada mais, nada menos.",
  "cmp-v-25k": "25.000 AEQ",
  "cmp-v-1k": "1.000 AEQ",
  "eco-label": "A economia",
  "eco-h2": "Um ciclo, três papéis",
  "eco-sub": "As pessoas recebem a renda básica e a gastam. As empresas a recebem e a repassam como salários e compras. O que fica parado ou sai da rede volta à renda básica e, dali, igualmente para todos.",
  "eco-svg-people": "Pessoas",
  "eco-svg-biz": "Empresas",
  "eco-svg-ubi": "Renda básica",
  "eco-svg-buy": "compras",
  "eco-svg-wages": "salários",
  "eco-svg-daily": "diariamente, igual para todos",
  "eco-svg-levies": "dinheiro parado · saída · taxas",
  "eco-p1-h": "O dinheiro só é criado para pessoas",
  "eco-p1-p": "Cada pessoa verificada recebe 1.000 AEQ uma vez. Ninguém mais cria dinheiro: nem empresas, nem validadores, nem fundadores.",
  "eco-p2-h": "A circulação é recompensada",
  "eco-p2-p": "Comprar, pagar salários e pagar fornecedores custa pouco ou nada. Dinheiro parado além de limites claros paga um pequeno encargo mensal.",
  "eco-p3-h": "Cada encargo volta para todos",
  "eco-p3-p": "Taxas de transferência, encargos sobre dinheiro parado e encargos de saída vão 100 % para a renda básica, paga todos os dias em partes iguais a cada pessoa verificada.",
  "cmp-label": "Pessoa ou empresa?",
