  "cmp-sub": "Ninguém verifica o que você é. As regras tornam a acumulação cara em qualquer forma e passar o dinheiro adiante barato, então cada um escolhe a conta que realmente lhe serve.",
  "cmp-col-rule": "Regra",
  "cmp-col-person": "Pessoa",
