  "cmp-r3": "Dinheiro parado",
  "cmp-r3-p": "0,5 % ao mês, só acima de 5.000 AEQ",
  "cmp-r3-b": "dinheiro com mais de 30 dias 1 % ao mês, mais de 90 dias 3 %; 2.000 AEQ sempre livres",
  "cmp-r3-f": "1 % ao mês",
