  "biz-r5-k": "Para onde vai",
  "biz-r5-v": "Cada encargo vai 100 % para a renda básica, igualmente para cada pessoa",
  "biz-open": "<strong>Abrir uma conta de empresa:</strong> uma pessoa verificada e a carteira da empresa assinam juntas. No máximo 3 empresas por pessoa e até 10 responsáveis por empresa. Sem junta comercial e sem porteiro: ninguém verifica o que você é, as regras tornam a acumulação cara em qualquer forma. Em breve no aplicativo.",
  "biz-live-from": "Regras valem a partir de",
