  "how-sub": "محفظة على هاتفك، التقاط حي قصير للوجه، ومنحة لمرة واحدة — دون حساب مصرفي.",
  "step1-h": "امسح",
  "step1-p": "محفظة على هاتفك؛ يلتقط التطبيق وجهك مع تحدٍّ عشوائي لتدوير الرأس، وتقارنه خدمتا مطابقة مستقلتان بكل المسجَّلين منذ بدء التحقق من الوجه. تُتلَف الصور؛ وتحتفظ كل خدمة بقالب مشفَّر.",
  "step2-h": "إثبات",
  "step2-p": "برهان معرفة صفرية للسلسلة: هذه الهوية المرتبطة بالوجه غير مسجَّلة بعد (nullifier). لا يقبله خادم البراهين إلا مع شهادة موقَّعة من خدمات المطابقة.",
  "step3-h": "استلام",
  "step3-p": "1,000 AEQ مرة واحدة لكل تسجيل ناجح.",
  "sybil-blurb": "<strong>Sybil / الحماية:</strong> تحقق حي من الوجه (نصاب 2 من خدمات مستقلة) + شهادة موقَّعة + nullifier على السلسلة يُستهلك مرة واحدة. حدود مُعلنة: الحسابات المسجَّلة قبل التحقق من الوجه (2026-08-25 — كل حسابات اليوم الـ18 تقريباً) لا تملك قالب وجه؛ عتبة المطابقة لم تُعايَر بعد على التقاطات حقيقية؛ فحص الحيوية هو تدوير الرأس، وتبقى التزييفات العميقة المتقدمة خطراً متبقياً؛ وضع تقسيم الحصص (<code>MPC</code>) يعمل في الظل، وما زالت كل خدمة تحتفظ بقالب مشفَّر كامل.",
  "how-link": "سجّل واحصل على 1,000 AEQ →",
  "why-label": "العدالة",
  "why-h2": "معامل جيني للبيتكوين ~0.85 — أعلى من أي دولة",
  "why-sub": "العرض = بشر موثّقون × 1,000 AEQ. Gini من العقدة الحية. Go L1 مصدر حقيقة السجل (وليس عقد المرآة وحده).",
  "why-link": "منحنى لورنز والسجل ومقارنة الدول →",
  "disc-title": "تنبيه Phase 1",
  "disc-body": "Phase 1: منذ 2026-08-25 يرفض خادم البراهين أي تسجيل بلا شهادة موقَّعة من نصاب المطابقة — لم يعد الهاتف الثاني يمنح الوجه نفسه حساباً ثانياً. ما لا يصح بعد: الحسابات السابقة لذلك التاريخ لا تملك قالب وجه ويمكنها مبدئياً التسجيل مجدداً بمحفظة جديدة؛ نسب الخطأ غير مُعايَرة (يلزم نحو 1,000 زوج منتحل)؛ فحص الحيوية هو تدوير الرأس، ودفاعات أقوى ضد التزييف العميق قيد المعايرة. اقرأ «إنسان واحد، حساب واحد» بمعنى «مُتحقَّق منه، بحدود مُعلنة» — لا بمعنى «يستحيل تجاوزه».",
  "oss-line": "<strong>مفتوح المصدر:</strong> السلسلة الأساسية عامة · خدمات الهوية/البرهان خاصة جزئياً في Phase 1.",
  "rest-label": "بقية الموقع",
  "rest-h2": "كل ما عدا ذلك له قسمه الخاص",
  "rest-sub": "تتوقف هذه الصفحة هنا عن قصد. كل قسم في الأسفل يحتوي على التفاصيل — تقدّمها هذه العقدة مباشرة، بدل كتابتها هنا مرة ثانية.",
  "card-register-d": "وثّق نفسك واحصل على 1,000 AEQ التي تأتي مع كونك إنسانًا.",
  "card-explorer-d": "الكتل والمعاملات وسجل البشر لحظة حدوثها.",
  "card-equality-d": "معامل جيني كاملًا: منحنى لورنز والسجل وسقف الثروة.",
  "card-network-d": "الإجماع والعقد والدخل الأساسي والرسم على الاكتناز والأوصياء — القواعد نفسها.",
  "card-exchange-d": "المبادلة والسيولة. رسوم التحويل تذهب 100٪ إلى الدخل الأساسي؛ ورسوم المبادلة تُقسَّم <bdi>40 / 30 / 30</bdi>.",
