  "biz-b3-p": "يمكن للفرد أن يملك 25,000 AEQ كحد أقصى، أما الشركات فليس لها حد ثابت. المال الذي يواصل التداول خلال 30 يومًا لا يكلّف شيئًا أبدًا.",
