  "biz-open": "<strong>فتح حساب شركة:</strong> يوقّع شخص موثَّق ومحفظة الشركة معًا. 3 شركات كحد أقصى لكل شخص، وحتى 10 مسؤولين لكل شركة. لا سجل تجاري ولا حارس بوابة: لا أحد يتحقق مما أنت عليه، فالقواعد تجعل الاكتناز مكلفًا بكل أشكاله. قريبًا في التطبيق.",
