  "ubi-sub": "لا يُنشأ مال من أجل الدخل الأساسي. يُدفع فقط مما تجمعه الشبكة، وكل ما يُجمع يُوزَّع.",
  "ubi-c1-h": "البداية: 1,000 AEQ",
  "ubi-c1-p": "يحصل كل شخص موثَّق عند التسجيل مرة واحدة على 1,000 AEQ: الحصة العادلة. كمية النقود دائمًا = عدد الأشخاص الموثَّقين × 1,000 AEQ.",
