  "fee-note": "تُضاف الرسوم فوق المبلغ: يستلم المستفيد دائمًا المبلغ كاملًا، فسعر 10 AEQ يجلب للمتجر 10 AEQ بالضبط. اعتبارًا من 1 أكتوبر 2026 تكون أول 1,000 AEQ ينفقها الشخص شهريًا مجانية، ولا تكلّف الرواتب من الشركات إلى الأفراد شيئًا. بين الشركات 0.1% دون زيادة.",
