  "ex-ben-h": "بِن يعمل في مقهى",
  "ex-ben-p": "يتقاضى 2,000 AEQ راتبًا، وينفق 1,500 AEQ، ويحوّل 1,000 AEQ إلى يورو للإيجار. رسوم على 500 AEQ فوق المبلغ المعفى: 0.5 AEQ. رسوم المبادلة العادية: 1 AEQ. لا اقتطاع خروج لأنه راتبه.",
  "ex-ben-r": "يدفع 1.5 AEQ شهريًا",
  "ex-clara-h": "لدى كلارا 20,000 AEQ",
  "ex-clara-p": "تنفق 3,000 AEQ شهريًا وتحوّل 5,000 AEQ. التحويلات: 2,000 × 1.1% = 22 AEQ. المال الراكد: 15,000 × 0.5% = 75 AEQ. التحويل: 4,000 × 2% = 80 AEQ (أول 1,000 معفاة). كل ذلك يذهب إلى الدخل الأساسي، أي إلى آنا وبِن أيضًا.",
  "ex-clara-r": "تدفع 177 AEQ شهريًا",
  "ex-cafe-h": "مقهى",
  "ex-cafe-p": "يحصّل 3,000 AEQ شهريًا ويدفع 1,500 رواتب و800 للمورّد و600 للمالكة. يواصل المال طريقه خلال الشهر، ولا شيء يتجاوز 30 يومًا، فلا اقتطاع على المال الراكد. فقط الدفع للمورّد يكلّف 0.1%.",
  "ex-cafe-r": "يدفع 0.8 AEQ شهريًا",
  "ex-market-h": "سوبرماركت يكتنز",
  "ex-market-p": "يمر عبره 40,000 AEQ شهريًا، لكن 200,000 AEQ تبقى في الحساب. يُنفق المال الأقدم أولًا، لذا 40,000 AEQ أحدث من 30 يومًا، و80,000 بين 30 و90 يومًا، و80,000 أقدم: 80,000 × 1% + (80,000 − 2,000) × 3%. إن دفع رواتب بدلًا من ذلك، ينخفض الاقتطاع ويصل المال إلى الناس مباشرة.",
  "ex-market-r": "يدفع نحو 3,140 AEQ شهريًا إلى الدخل الأساسي",
  "ex-hoard-h": "شخص يريد اكتناز 100,000 AEQ",
  "ex-hoard-p": "كفرد: مستحيل، فالحد 25,000 AEQ. على 100 عنوان آخر بـ 1,000 AEQ لكل منها: 1% شهريًا = 1,000 AEQ شهريًا. كـ«شركة»: 980 AEQ شهريًا في الشهرين الثاني والثالث، ثم 98,000 × 3% = 2,940 AEQ شهريًا.",
  "ex-hoard-r": "الاكتناز لا يربح بأي شكل (نحو 35% سنويًا)",
