  "age-r2-v": "يحتفظ بعمره",
  "age-r3-k": "من شخص احتفظ به 30 يومًا على الأقل",
  "age-r3-v": "جديد: كان فعلًا مال ذلك الشخص",
  "age-r4-k": "أُنشئ حديثًا: الدخل الأساسي، التسجيل، التحويل إلى AEQ",
  "age-r4-v": "جديد",
  "age-note": "تنفق الشركة دائمًا أقدم أموالها أولًا، وهو الترتيب الأرخص لها. أما للأفراد فلا يهم العمر؛ إنما يُنقل فقط لتحصل عليه الشركات بشكل صحيح.",
  "biz-r6-k": "علني",
  "biz-r6-v": "الاسم والفئة وعدد المسؤولين ظاهرة في المستكشف. لا يمكن إغلاق الحساب إلا وهو فارغ؛ ويُدفع الرصيد قبل ذلك للأفراد دون رسوم.",
  "shop-label": "للمتاجر",
  "shop-h2": "كيف يشارك المتجر",
  "shop-sub": "ما يحتاجه المخبز ليقبل AEQ.",
  "shop-1-h": "الدفع برمز QR",
  "shop-1-p": "أدخل المبلغ، اعرض رمز QR، يمسحه الزبون ويدفع ويحصل على إيصال. الأسعار بـ AEQ أو بما يعادلها باليورو بالسعر الحالي.",
  "shop-2-h": "تصدير محاسبي",
  "shop-2-p": "كل دفعة بتاريخها ومبلغها بـ AEQ وقيمتها باليورو وقت الدفع، في ملف CSV للمستشار الضريبي.",
  "shop-3-h": "التحويل فورًا، إن شئت",
  "shop-3-p": "من لا يريد مخاطر سعر الصرف يحوّل إيراداته فورًا (2%). الخيار يبقى للمتجر.",
  "shop-4-h": "لماذا يستحق ذلك",
  "shop-4-p": "المدفوعات مجانية للمتجر، والرواتب بـ AEQ لا تكلّف شيئًا، والناس الذين لديهم دخل أساسي يبحثون عن أماكن لإنفاقه.",
  "shop-status": "<strong>الوضع:</strong> القواعد على السلسلة مبنية وتسري اعتبارًا من 1 أكتوبر 2026. وضع الصندوق والتصدير في التطبيق قيد العمل.",
  "lh-label": "الحماية من الإساءة",
  "lh-h2": "من هي الشركة؟ لا نحتاج إلى معرفة ذلك.",
  "lh-sub": "لا تستطيع شبكة لامركزية التحقق مما إذا كانت هناك شركة حقيقية خلف حساب ما، ولا ينبغي لها ذلك: لا سجل تجاري ولا جهة رسمية ولا حارس بوابة. بدلًا من ذلك، الاكتناز مكلف بكل أشكاله وتمرير المال رخيص بكل أشكاله. التسجيل كشركة لا يفيد إلا من يتدفق ماله فعلًا.",
  "lh-list-h": "كل طرق الالتفاف التي وجدناها، ولماذا تفشل",
  "lh-1": "<strong>التسجيل كشركة للتحايل على حد 25,000.</strong> اقتطاع 1–3% شهريًا أغلى من أي شكل آخر.",
  "lh-2": "<strong>تدوير المال بين شركاتك أو شركات صديقة.</strong> العمر ينتقل مع المال؛ بين الشركات لا شيء يصبح أحدث، مهما طالت الدائرة.",
  "lh-3": "<strong>إعادته عبر المالك أو صديق.</strong> إن بقي المال لدى ذلك الشخص أقل من 30 يومًا، احتفظ بعمره.",
  "lh-4": "<strong>إيداعه فعلًا لدى أصدقاء لمدة 30 يومًا.</strong> يمكن لكل شخص أن يحمل 25,000 AEQ كحد أقصى ويدفع الزيادة ذهابًا وإيابًا: نحو 2–2.5% في كل جولة لتوفير 1–3%، مع كامل المخاطرة.",
  "lh-5": "<strong>تأسيس شركات كثيرة للحصول على إعفاءات كثيرة.</strong> 3 حسابات شركات كحد أقصى لكل شخص، أي 6,000 AEQ معفاة كحد أقصى.",
  "lh-6": "<strong>أن تدفع لنفسك «كموظف».</strong> المدفوعات للمسؤولين سحوبات وليست رواتب.",
  "lh-7": "<strong>رواتب وهمية لأصدقاء يحوّلونها ويعيدون النقد.</strong> الراتب معفى من اقتطاع الخروج حتى 3,000 AEQ فقط لكل شخص شهريًا، ومجاميع الرواتب علنية.",
  "lh-8": "<strong>«تجديد» المال عبر صندوق السيولة.</strong> السيولة يقدّمها الأفراد فقط.",
  "lh-9": "<strong>عقد ذكي كمخبأ.</strong> العقود عناوين أخرى: 1,000 AEQ كحد أقصى، 1% شهريًا.",
  "lh-honest": "<strong>ما يبقى بصدق:</strong> لا يستطيع أي نظام نقدي في العالم منع كثير من الناس الحقيقيين من التواطؤ. هنا يكلّف كل تواطؤ معروف أكثر مما يوفّر، أو يبقى محدودًا بمبالغ صغيرة. مبيعات الشركات ومجاميع الرواتب علنية، فتظهر الأنماط غير المعتادة. من يجد ثغرة جديدة يبلّغ عنها، وتُعدَّل القواعد.",
  "rm-label": "خارطة الطريق",
  "rm-h2": "ما التالي",
  "rm-1-h": "الآن: المرحلة 1",
  "rm-1-p": "تسجيل مع فحص حيّ للوجه عبر خدمتي مطابقة مستقلتين. 1,000 AEQ في البداية، ودخل أساسي كل يوم.",
  "rm-2-h": "1 أكتوبر 2026",
