  "cmp-r4-f": "0.1 %",
  "cmp-r5": "यूरो या डॉलर में बदलना",
  "cmp-r5-p": "वेतन और हर महीने 1,000 AEQ मुफ़्त, फिर 2 %",
  "cmp-r5-b": "2 %",
  "cmp-r6": "कौन खोलता है",
  "cmp-r6-p": "हर सत्यापित व्यक्ति, एक बार",
  "cmp-r6-b": "एक से दस सत्यापित लोग; प्रति व्यक्ति अधिकतम 3",
  "cmp-r6-f": "कोई भी",
  "cmp-note": "ये नियम 1 अक्टूबर 2026 से लागू हैं। हर कटौती 100 % बुनियादी आय में जाती है।",
  "ppl-label": "लोगों के लिए",
  "ppl-h2": "हर व्यक्ति से छह वादे",
  "ppl-sub": "सबसे निष्पक्ष पैसा पहले उस व्यक्ति को निष्पक्ष लगना चाहिए जिसके पास कम है।",
  "ppl-1": "<strong>आपका उचित हिस्सा अछूता है।</strong> पहले 1,000 AEQ पर कभी कटौती नहीं होती।",
  "ppl-2": "<strong>रोज़मर्रा की ज़िंदगी में कोई खर्च नहीं।</strong> हर महीने खर्च किए गए पहले 1,000 AEQ शुल्क-मुक्त हैं।",
  "ppl-3": "<strong>वेतन वेतन है।</strong> हर महीने 3,000 AEQ तक वेतन और साथ में 1,000 AEQ बिना कटौती बदले जाते हैं।",
  "ppl-4": "<strong>बचत की अनुमति है।</strong> 5,000 AEQ तक आपकी बचत कुछ नहीं खोती।",
  "ppl-5": "<strong>जिसके पास ज़्यादा है, वह ज़्यादा देता है।</strong> शुल्क सिर्फ़ बड़े शेष पर बढ़ता है; 25,000 AEQ की सीमा बनी रहती है।",
  "ppl-6": "<strong>रखने और निकालने के लिए लोग हमेशा व्यवसायों से कम चुकाते हैं,</strong> और कोई भी जो चुकाता है, वह सभी लोगों को बराबर लौटता है।",
  "biz-label": "व्यवसायों के लिए",
  "biz-h2": "AEQ स्वीकार करें, आगे बढ़ाएँ, कुछ न चुकाएँ",
  "biz-sub": "व्यवसाय AEQ स्वीकार कर सकते हैं, रख सकते हैं और खर्च कर सकते हैं। नियम पैसे को उनके ज़रिए लोगों तक वापस पहुँचाते हैं: पैसा रोककर रखने की कीमत है, आगे बढ़ाना मुफ़्त है।",
  "biz-b1-h": "कोई कार्ड शुल्क नहीं",
  "biz-b1-p": "भुगतान से व्यवसाय का कुछ खर्च नहीं होता। ग्राहक हर महीने पहले 1,000 AEQ बिना शुल्क खर्च करते हैं।",
  "biz-b2-h": "शुल्क-मुक्त वेतन",
  "biz-b2-p": "AEQ में दिया गया वेतन कुछ खर्च नहीं करता। कर्मचारी हर महीने 3,000 AEQ तक वेतन बिना कटौती यूरो या डॉलर में बदल सकते हैं।",
  "biz-b3-h": "विकास की कोई सीमा नहीं",
  "biz-b3-p": "लोग अधिकतम 25,000 AEQ रख सकते हैं; व्यवसायों की कोई तय सीमा नहीं। 30 दिनों के भीतर आगे बढ़ने वाला पैसा कभी कुछ खर्च नहीं करता।",
  "biz-b4-h": "सेकंडों में भुगतान",
  "biz-b4-p": "पैसा सेकंडों में पहुँचता है। कोई चार्जबैक नहीं, निपटान का इंतज़ार नहीं।",
  "biz-rules-h": "नियम",
  "biz-r1-k": "रुका हुआ पैसा",
  "biz-r1-v": "30 दिन से पुराना: 1 % प्रति माह · 90 दिन से पुराना: 3 % प्रति माह · 2,000 AEQ हमेशा मुफ़्त",
  "biz-r2-k": "पैसे की एक उम्र होती है",
  "biz-r2-v": "उम्र पैसे के साथ चलती है। अपनी कंपनियों या दोस्तों के ज़रिए पैसा घुमाने से वह नया नहीं होता। किसी व्यक्ति के पास 30 दिन रहने के बाद ही वह नया होता है।",
  "biz-r3-k": "यूरो या डॉलर में निकासी",
  "biz-r3-v": "2 % कटौती। लोग: वेतन और हर महीने 1,000 AEQ मुफ़्त",
  "biz-r4-k": "व्यवसायों के बीच",
  "biz-r4-v": "0.1 %, कोई अतिरिक्त शुल्क नहीं",
  "biz-r5-k": "यह कहाँ जाता है",
  "biz-r5-v": "हर कटौती 100 % बुनियादी आय में जाती है, हर व्यक्ति को बराबर",
  "biz-open": "<strong>व्यवसाय खाता खोलना:</strong> एक सत्यापित व्यक्ति और व्यवसाय का वॉलेट साथ में हस्ताक्षर करते हैं। प्रति व्यक्ति अधिकतम 3 व्यवसाय, प्रति व्यवसाय 10 तक ज़िम्मेदार लोग। न कोई रजिस्ट्री, न कोई द्वारपाल: कोई नहीं जाँचता कि आप कौन हैं, नियम हर तरह की जमाखोरी को महँगा बनाते हैं। जल्द ही ऐप में।",
