  "ubi-c1-h": "शुरुआत: 1,000 AEQ",
  "ubi-c1-p": "हर सत्यापित व्यक्ति को पंजीकरण पर एक बार 1,000 AEQ मिलते हैं: उचित हिस्सा। कुल मुद्रा हमेशा सत्यापित लोग × 1,000 AEQ होती है।",
